"""Build a review-only static site. No accounts, credentials or orders are published."""
from pathlib import Path
import json,html,shutil,subprocess,os
R=Path('site');A=R/'assets';R.mkdir(exist_ok=True);A.mkdir(exist_ok=True)
if Path('tools/recover-brand.py').exists() and not (A/'brand-media.json').exists(): subprocess.run(['python3','tools/recover-brand.py'],check=False)
D=json.loads(Path('src/catalog.json').read_text()); E=html.escape
if Path('src/site.css').exists():shutil.copy('src/site.css',A/'site.css')
if Path('src/site.js').exists():shutil.copy('src/site.js',A/'site.js')
(A/'catalog.json').write_text(json.dumps(D,ensure_ascii=False,indent=2))
CATS={'wochenkarte':'Wochenkarte','klassiker':'Unsere Klassiker','weisswein':'Weißwein','rotwein':'Rotwein'}
PCATS={'conservas':'Konserven','embutidos':'Wurst & Cecina','weisswein':'Weißwein','rotwein':'Rotwein'}
logo=next((x for x in ['original-logo.svg','original-logo.webp'] if (A/x).exists()),None)
def money(c):return f'{c/100:.2f}'.replace('.',',')+' €'
def pic(root,name,alt,cls='',lazy=True):return f'<img src="{root}assets/{name}.webp" alt="{E(alt)}" class="{cls}" '+('loading="lazy" ' if lazy else 'fetchpriority="high" ')+ 'decoding="async">'
def page(path,title,body,theme='',desc='Vinería del Este: spanische Tapas, Wein und Spezialitäten in Berlin-Friedrichshain.',area='restaurant'):
    p=Path(path);depth=len(p.parts)-1;root='../'*depth; base=root+('editorial/' if theme else '')
    brand=f'<img src="{root}assets/{logo}" alt="Vineria del Este">' if logo else 'Vineria del Este<small>Tapas · Wein · Berlin</small>'
    active_shop=' aria-current="page"' if area=='shop' else ''
    config={'root':root,'home':base+'index.html','shop':base+'shop/index.html','theme':theme,'products':D['products'],'mode':'review'}
    data=json.dumps(config,ensure_ascii=False).replace('<','\\u003c')
    navigation=f'''<div class="review"><span>DESIGNVORSCHAU · Keine Bestellungen oder Zahlungen · Preise im Shop sind Beispiele</span><a href="{root}entwuerfe/index.html">Entwürfe ansehen ↗</a></div><header class="header"><div class="wrap nav"><a class="brand" href="{base}index.html">{brand}</a><nav id="navigation" class="navigation" aria-label="Hauptnavigation"><a href="{base}index.html#speisekarte">Speisekarte</a><a class="optional" href="{base}index.html#vineria">Die Vineria</a><a class="optional" href="{base}index.html#besuch">Besuch</a><a href="{base}shop/index.html"{active_shop}>Tienda</a><a href="{base}warenkorb/index.html">Warenkorb <span data-cart-count>0</span></a></nav><div class="nav-actions"><a class="btn outline" href="https://vineriaytapas.de/#tebi-reservations" target="_blank" rel="noopener">Reservieren ↗</a><a class="btn" href="{base}shop/index.html">Unser Shop ↗</a></div><button class="mobile-menu" aria-controls="navigation" aria-expanded="false">Menü</button></div></header>'''
    footer=f'''<footer class="footer"><div class="wrap"><div class="footer-top"><div><div class="footer-word" lang="es">Hasta pronto.</div><p class="note">Vineria del Este · Bänschstraße 41 · Berlin</p></div><nav class="footer-links" aria-label="Service"><a href="{base}shop/index.html">Unser Shop</a><a href="{base}service/index.html#versand">Versand & Abholung</a><a href="{base}service/index.html#widerruf">Widerruf & Retouren</a><a href="{base}service/index.html#agb">AGB</a><a href="{base}service/index.html#datenschutz">Datenschutz</a><a href="{base}service/index.html#impressum">Impressum</a><a href="https://www.instagram.com/vineria.del.este/" target="_blank" rel="noopener">Instagram ↗</a><a href="{root}verwaltung/index.html">Verwaltung</a></nav></div><div class="footer-bottom"><span>Entwurf 06 · {'Editorial / Creme & Wein' if theme else 'Fanzine / Papier & Fotokopie'} · 19.09.2026</span><a href="{root}entwuerfe/index.html#herkunft">Bildnachweise & Projektstand</a></div></div></footer>'''
    out=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="description" content="{E(desc)}"><meta name="referrer" content="strict-origin-when-cross-origin"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="Designvorschau · Restaurant und Tienda · Keine aktive Verkaufsseite"><title>{E(title)}</title><link rel="stylesheet" href="{root}assets/site.css"><script>window.VDE={data};</script><script src="{root}assets/site.js" defer></script></head><body class="{theme}"><a class="skip" href="#main">Zum Inhalt</a>{navigation}<main id="main">{body}</main>{footer}<div id="toast" class="toast" role="status" hidden></div></body></html>'''
    target=R/p;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(out)
def menu():
    tabs=''.join(f'<button type="button" id="tab-{k}" data-tab="{k}" aria-controls="{k}">{E(v)}</button>' for k,v in CATS.items())
    panels=''
    for key,title in CATS.items():
        rows=''.join(f'<article class="dish"><div class="dish-head"><h4>{E(n)}</h4><span class="price">{money(c)}</span></div><p>{E(d)}</p></article>' for n,d,c in D['menu'][key])
        panels+=f'<section class="menu-panel" id="{key}" aria-labelledby="tab-{key}"><h3>{title}</h3><div class="dishes">{rows}</div></section>'
    return f'''<section class="menu-section" id="speisekarte"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Unsere Karte · Zum Teilen</p><h2>Was auf den<br>Tisch kommt.</h2></div><p>Unsere Wochenkarte wechselt. Die Klassiker bleiben. Dazu ein Glas aus unserer Weinauswahl.</p></div><div class="tabs">{tabs}</div>{panels}<p class="note">Kartenstand der bisherigen Website: September 2026. Verfügbarkeit, Jahrgänge und Preise vor dem Besuch bestätigen. Informationen zu Allergenen erhaltet Ihr im Restaurant.</p></div></section>'''
def art(root,p):
    if p['case']:img=pic(root,'wine-art','Grafische Wein-Illustration, kein Produktfoto')
    else:img=f'<div class="abstract-pack">{E(p["name"])}<small>{E(p["pack"])}</small></div>'
    return f'<div class="product-art">{img}<span class="art-caption">Grafik · Produktfoto folgt</span></div>'
def choices(p):
    return f'<select aria-label="Format für {E(p["name"])}" data-variant><option value="single">{E(p["pack"])} · {money(p["price"])}</option>'+ (f'<option value="case">6 × 0,75 l · {money(p["casePrice"])}</option>' if p['case'] else '')+'</select>'
def unit(p):return money(round(p['price']*1000/p['amount']))+('/l' if p['unit']=='ml' else '/kg')
def card(root,base,p):
    return f'''<article class="product-card" data-product="{p['id']}" data-category="{p['category']}"><a href="{base}shop/{p['id']}/index.html" aria-label="{E(p['name'])}">{art(root,p)}</a><div class="eyebrow">{E(p['brand'])} · {E(p['pack'])}</div><h2><a href="{base}shop/{p['id']}/index.html">{E(p['name'])}</a></h2><p>{E(p['description'])}</p><div class="buy-row"><span class="price" data-price>{money(p['price'])}</span><span class="note">{'Nur Abholung' if p['pickup'] else 'Beispielpreis'}</span></div><div class="unit" data-unit>{unit(p)} · zzgl. Versand</div>{choices(p)}<button class="btn" data-add="{p['id']}">In den Warenkorb +</button></article>'''
for theme in ['', 'editorial']:
    pre='editorial/' if theme else '';root='../' if theme else '';base=''
    scene=f'''<div class="scene" data-slideshow><div class="cutout">{pic(root,'collage','Künstlerische Fotocollage aus bereitgestellten Porträts: zwei Menschen an einem Tisch','active',False)}</div><div class="cutout">{pic(root,'terrasse','Originalaufnahme: Service auf der Terrasse der Vineria')}</div><div class="cutout">{pic(root,'portrait','Originalporträt aus der Vineria')}</div><span class="scene-star" aria-hidden="true">✳</span><div class="scene-sticker">GUTER WEIN.<br>GUTE GESELLSCHAFT.</div><div class="scene-controls"><button data-prev aria-label="Vorheriges Bild">←</button><span data-slide-number>01 / 03</span><button data-next aria-label="Nächstes Bild">→</button><button data-pause aria-pressed="false">Pause</button></div><p class="scene-caption">Originalfotos und eine künstlerische Fotocollage aus dem eigenen Bildmaterial. Keine Aufnahme eines tatsächlich fotografierten gemeinsamen Tischmoments.</p></div>'''
    if theme:
        scene=scene.replace('class="active"','class=""',1).replace('alt="Originalaufnahme: Service auf der Terrasse der Vineria" class=""','alt="Originalaufnahme: Service auf der Terrasse der Vineria" class="active"')
    restaurant=f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">Bänschstraße 41 · Berlin–Friedrichshain</p><h1>Wein.<br>Tapas.<br><em>Leben.</em></h1><p>Spanisch-uruguayische Küche, kleine Teller und ein gutes Glas. Ein Ort, um zusammenzukommen. Und noch ein bisschen zu bleiben.</p><div class="actions"><a class="btn" href="#speisekarte">Speisekarte ↓</a><a class="btn outline" href="shop/index.html">Unsere Tienda ↗</a></div></div>{scene}</section><div class="wrap strip"><span>Tapas & Wein</span><i>✳</i><span>Friedrichshain</span><i>✳</i><span>Restaurant & Tienda</span><i class="optional">✳</i><span class="optional">Zusammensein</span></div><section class="intro wrap" id="vineria"><h2>Kleine Teller.<br>Große Abende.</h2><div><p>Etwas auf dem Tisch. Ein Wein, über den man ins Gespräch kommt. Und die Menschen, mit denen man gerne noch ein bisschen bleibt.</p><a class="text-link" href="#besuch">Zu Besuch in der Bänschstraße ↗</a></div></section>{menu()}<section class="shop-teaser wrap"><div class="teaser-image">{pic(root,'wine-art','Künstlerische Illustration einer Weinflasche mit zwei Gläsern')}<span class="tape" aria-hidden="true"></span></div><div><p class="eyebrow">Unsere Tienda · Für zu Hause</p><h2>Ein Stück Vineria.<br>Auch für morgen.</h2><p>Euch gefällt unsere Auswahl? Einige unserer Weine und spanischen Spezialitäten könnt Ihr auch mit nach Hause nehmen. Entdeckt unsere Tienda – zum Verschenken, zum Teilen oder für den nächsten Abend am eigenen Tisch.</p><a class="btn" href="shop/index.html">Unsere Auswahl entdecken ↗</a><p class="note">Shop-Vorschau mit Beispielsortiment. Noch kein Verkauf.</p></div></section><div class="gallery wrap"><figure>{pic(root,'terrasse','Originalaufnahme der Terrasse und des Service')}<figcaption>Draußen in der Bänschstraße.</figcaption></figure><figure>{pic(root,'portrait','Originalporträt aus dem bereitgestellten Vineria-Archiv')}<figcaption>Die Menschen hinter der Vineria.</figcaption></figure><figure>{pic(root,'bar','Originalaufnahme an der Bar')}<figcaption>Ein guter Abend fängt hier an.</figcaption></figure></div><section class="statement"><div class="wrap"><h2>Der beste Platz?<br>Zusammen.</h2><p>Ein bisschen Spanien. Ein bisschen Uruguay. Und ganz viel Berlin.<br><br><span lang="es">¡Salud!</span></p></div></section><section class="visit wrap" id="besuch"><div><p class="eyebrow">Wir sehen uns im Kiez</p><h2>Komm vorbei.</h2><p class="address">Bänschstraße 41<br>10247 Berlin</p><a class="btn outline" href="{E(D['map'])}" target="_blank" rel="noopener">Route planen ↗</a><div class="contact"><a href="tel:+493042024943">+49 30 42024943</a><br><a href="mailto:vineriadeleste@gmail.com">vineriadeleste@gmail.com</a></div></div><div><p class="eyebrow">Öffnungszeiten</p><div class="hours"><div><span>Dienstag – Donnerstag</span><span>ab 16 Uhr</span></div><div><span>Freitag – Samstag</span><span>ab 15 Uhr</span></div><div><span>Sonntag</span><span>12 – 18 Uhr</span></div><div><span>Montag</span><span>geschlossen</span></div></div><p class="note">Küche Dienstag – Samstag bis ca. 22 Uhr.<br>Reservierungen öffnen die bisherige Website mit Tebi.</p><div class="actions"><a class="btn" href="https://vineriaytapas.de/#tebi-reservations" target="_blank" rel="noopener">Tisch reservieren ↗</a><a class="btn outline" href="shop/index.html">Zum Shop ↗</a></div></div></section>'''
    page(pre+'index.html','Vineria del Este · Tapas, Wein & Tienda in Berlin',restaurant,theme)
    root='../../' if theme else '../';base='../'
    filters='<button data-filter="all" aria-pressed="true">Alles</button>'+''.join(f'<button data-filter="{k}" aria-pressed="false">{v}</button>'for k,v in PCATS.items())
    cards=''.join(card(root,base,p)for p in D['products'])
    shop=f'''<section class="hero shop-hero wrap"><div class="hero-copy"><p class="eyebrow">Vineria del Este · Tienda</p><h1>Für den Tisch.<br><em>Für zu Hause.</em></h1><p>Unsere Auswahl spanischer Spezialitäten und Weine. Die Vineria für Euren nächsten Abend – ein kleines Stück davon, gut ausgesucht.</p><a class="text-link" href="#sortiment">Sortiment entdecken ↓</a></div><div class="scene">{pic(root,'wine-art','Grafische Wein-Illustration')}<span class="scene-star" aria-hidden="true">✳</span></div></section><div class="wrap strip"><span>Spanische Spezialitäten</span><i>✳</i><span>Wein · Flasche & Karton</span><i class="optional">✳</i><span class="optional">Abholung in Berlin</span></div><section class="wrap" id="sortiment"><div class="toolbar"><div class="filters" aria-label="Produktkategorie">{filters}</div><input class="search" data-search type="search" aria-label="Produkt suchen" placeholder="Etwas Bestimmtes gesucht?"></div><p class="note" data-results>11 Produkte · Beispielsortiment</p><div class="products">{cards}</div><noscript><p class="nojs">Alle Produkte sind sichtbar. Für den Testwarenkorb bitte JavaScript aktivieren.</p></noscript><p class="notice">Designvorschau: alle Preise, Jahrgänge und Kartongrößen sind Beispiele. Produktgrafiken sind keine Fotos der verkauften Packungen. Produktkennzeichnung, Lagerung und Verfügbarkeit müssen vor Freigabe vollständig bestätigt werden.</p></section>'''
    page(pre+'shop/index.html','Spanische Spezialitäten & Wein · Vineria del Este Tienda',shop,theme,'Spanische Konserven, Chorizo, Cecina und Weine. Tienda der Vineria del Este in Berlin. Designvorschau mit Beispielpreisen.','shop')
    for p in D['products']:
        root='../../../' if theme else '../../';base='../../'
        source=p.get('source','https://vineriaytapas.de/')
        notes=p.get('note','Jahrgang aus der bisherigen Karte. Flaschenetikett, Alkoholgehalt, Zutaten, Nährwerte und gegebenenfalls Sulfite sind vor Verkauf zu bestätigen.')
        detail=f'''<div class="wrap"><nav class="breadcrumb" aria-label="Brotkrumennavigation"><a href="{base}index.html">Restaurant</a> / <a href="../index.html">Tienda</a> / {E(p['name'])}</nav><section class="detail" data-product="{p['id']}"><div>{art(root,p)}<p class="note">Abbildung: grafischer Platzhalter. Kein Originalproduktfoto.</p></div><div><p class="eyebrow">{E(p['brand'])} · {PCATS[p['category']]}</p><h1>{E(p['name'])}</h1><p class="description">{E(p['description'])}</p><div class="price" data-price>{money(p['price'])}</div><div class="unit" data-unit>{unit(p)} · Beispielpreis inkl. angenommener MwSt., zzgl. Versand</div>{choices(p)}<button class="btn" data-add="{p['id']}">In den Warenkorb +</button><p class="note">{'Vorläufig nur Abholung im Restaurant.' if p['pickup'] else 'Deutschland: ab 6,90 €; Weinpaket bis 6 Flaschen 9,90 €. Abholung kostenlos.'}</p><details open><summary>Produkt & Format</summary><p>{E(p['pack'])}. {('Karton: 6 Flaschen à 0,75 l (Planungsannahme). Jahrgang '+p.get('year','')+' aus der bisherigen Karte, nicht als verfügbar bestätigt.') if p['case'] else 'Kleines Packungsformat.'}</p></details><details><summary>Zutaten, Allergene & Aufbewahrung</summary><p>{E(notes)}</p><p>Die Pflichtinformationen sind noch nicht vollständig. Der Verkauf ist deshalb deaktiviert.</p></details><details><summary>Herkunft der Produktreferenz</summary><p><a href="{E(source)}" target="_blank" rel="noopener">Referenz beim Hersteller / Restaurant ↗</a>. Keine Lieferantenvereinbarung und kein bestätigter Einkaufspreis.</p></details><p class="notice">Es wird keine echte Bestellung ausgelöst. Keine Zahlungsdaten eingeben.</p></div></section></div>'''
        page(pre+'shop/'+p['id']+'/index.html',p['name']+' · Vineria del Este Tienda',detail,theme,p['description']+' Designvorschau.','shop')
    for route in ['warenkorb','checkout']:
        body='<div class="wrap"><p class="breadcrumb"><a href="../shop/index.html">← Weiter einkaufen</a></p><h1 class="page-title">'+('Euer Warenkorb.' if route=='warenkorb' else 'Fast am Tisch.')+'</h1><div id="'+route+'"></div><noscript><p class="nojs">Diese Testfunktion benötigt JavaScript. Die Produktseiten funktionieren ohne JavaScript.</p></noscript></div>'
        page(pre+route+'/index.html',('Warenkorb' if route=='warenkorb' else 'Test-Checkout')+' · Vineria del Este',body,theme,area='shop')
    service='''<article class="legal"><p class="eyebrow">Service · Entwurfsstand</p><h1>Gut zu wissen.</h1><p class="notice">Diese öffentliche Vorschau nimmt keine Bestellungen an. Die folgenden Informationen sind Arbeitsentwürfe, keine freigegebenen Verkaufsbedingungen. Vor Verkauf müssen Betreiber, Pflichtangaben, Versand, Zahlung und Rechtstexte bestätigt werden.</p><h2 id="versand">Versand & Abholung</h2><p>Planungswerte für Deutschland: Standardpaket 6,90 €. Weinpaket mit bis zu sechs Flaschen 9,90 €. Weitere Weinpakete werden separat berechnet. Abholung in der Bänschstraße 41 ist kostenlos. Lieferzeit als Annahme: 3–5 Werktage. Kühlpflichtige oder noch nicht für den Versand geprüfte Produkte stehen nur zur Abholung zur Auswahl.</p><h2 id="widerruf">Widerruf & Retouren</h2><p>In der Vorschau entsteht kein Kaufvertrag. Für den späteren Shop müssen eine vollständige Widerrufsbelehrung, ein Musterformular und ein erreichbarer elektronischer Widerrufsprozess eingerichtet werden. Lebensmittel werden nicht pauschal von Rückgaben ausgeschlossen; gesetzliche Ausnahmen sind je Produkt zu prüfen. Die Rücksendeadresse muss vom Betreiber bestätigt werden.</p><h2 id="agb">Bestellung & Zahlung</h2><p>Der Warenkorb und der Checkout dienen nur der Ansicht. Der Abschluss ist ausdrücklich eine Testbestellung ohne Zahlung und ohne Vertrag. Keine Bank- oder Kartendaten werden abgefragt. Es gibt keine Lieferzusage für Beispielartikel und keine tatsächliche Altersverifikation.</p><h2 id="datenschutz">Datenschutz der Vorschau</h2><p>Der Testwarenkorb wird nur lokal in diesem Browser gespeichert. Über „Warenkorb leeren“ lässt er sich löschen. Die Vorschau versendet keine Checkout-Formulare und speichert keine Adressen oder Zahlungsdaten auf dem Server. Eingaben sollen ausschließlich fiktiv sein. Hostinganbieter können technische Zugriffsdaten verarbeiten; die endgültige Datenschutzerklärung ist nach Wahl des Produktivhostings anzupassen.</p><h2 id="impressum">Impressum</h2><p>Restaurantkontakt: Vineria del Este, Bänschstraße 41, 10247 Berlin. Telefon +49 30 42024943. E-Mail vineriadeleste@gmail.com. Die Angaben zum rechtlichen Betreiber in der bestehenden Website sind widersprüchlich und müssen vor Produktivstart bestätigt werden.</p><p><a href="https://vineriaytapas.de/index.php/impressum" target="_blank" rel="noopener">Bisheriges Impressum ↗</a> · <a href="https://vineriaytapas.de/index.php/datenschutz" target="_blank" rel="noopener">Bisherige Datenschutzerklärung ↗</a></p></article>'''
    page(pre+'service/index.html','Service & Projektstand · Vineria del Este',service,theme)
admin='''<section class="admin-login"><p class="eyebrow">Separater Team-Zugang</p><h1>Verwaltung.</h1><p>Speisekarten, Sortiment und Teamkonten an einem Ort.</p><form id="admin-login"><label class="field">Benutzername<input name="username" autocomplete="username" required maxlength="80"></label><label class="field">Passwort<input name="password" type="password" autocomplete="current-password" required></label><button class="btn" type="submit">Anmelden →</button><p role="alert" id="login-message"></p></form><div class="notice">Im öffentlichen GitHub-Entwurf ist kein Verwaltungsserver aktiv. Der Zugang speichert oder übermittelt hier keine Passwörter. Die geschützte PHP-Verwaltung wird separat installiert; sie ist nicht durch eine bloße HTML-Sperre ersetzt.</div><a class="text-link" href="../index.html">Zurück zum Restaurant ↗</a></section>'''
page('verwaltung/index.html','Team-Zugang · Vineria del Este',admin)
portal=f'''<section class="wrap"><p class="eyebrow" style="margin-top:45px">Vineria del Este · Gemeinsame Designansichten</p><h1 class="page-title">Ein Haus.<br>Zwei Handschriften.</h1><p>Jeder Entwurf verbindet Restaurant und Tienda im gleichen Erscheinungsbild. Der Team-Zugang bleibt getrennt.</p><div class="review-cards"><article class="review-card">{pic('../','collage','Künstlerischer Fotocollage-Entwurf')}<p class="eyebrow">06A · Fanzine</p><h2>Papier. Menschen.<br>Ein gutes Glas.</h2><p>Fotokopie, gerissene Kanten und ein ruhiger, bewegter Bilderwechsel aus eigenem Material.</p><div class="actions"><a class="btn" href="../index.html">Restaurant öffnen</a><a class="btn outline" href="../shop/index.html">Tienda öffnen</a></div></article><article class="review-card">{pic('../','terrasse','Originalaufnahme der Restaurantterrasse')}<p class="eyebrow">06B · Editorial</p><h2>Creme. Wein.<br>Viel Raum.</h2><p>Die wärmere Alternative mit der bisherigen Farbwelt, Originalfotos und derselben Shop-Struktur.</p><div class="actions"><a class="btn" href="../editorial/index.html">Restaurant öffnen</a><a class="btn outline" href="../editorial/shop/index.html">Tienda öffnen</a></div></article></div><section id="herkunft" class="legal"><h2>Bildnachweise & Projektstand</h2><p>Die Originalporträts, die Terrasse und die Bar stammen aus dem vom Auftraggeber bereitgestellten Vineria-Archiv. Die Collage am kleinen Tisch wurde aus zwei dieser Porträts künstlerisch neu zusammengesetzt; sie zeigt keinen dokumentierten gemeinsamen Moment. Papiergrafik und Weinillustration wurden für diesen Entwurf generiert. Die Referenzbilder und der Referenzfilm wurden nicht als Website-Material veröffentlicht.</p><p>Originalmaterial der bisherigen Restaurant-Website wird mit Herkunft im <a href="../assets/media.json">Medienverzeichnis</a> und im <a href="../assets/brand-media.json">ergänzenden Verzeichnis</a> dokumentiert. Die bisherige Website nennt Steffen Wohlfarth für Fotografien und Pascal Gabet für Fliesenmotive. Die neue Illustration ist kein Werk von Karmen Kraft.</p><p>Shop-Preise, 6er-Kartons und Versandkosten sind Planungsbeispiele. Kein Zahlungssystem, kein Verkauf und kein geschützter Verwaltungsserver sind hier aktiv. Die technische Suchmaschinenstruktur der Tienda ist vorbereitet; die komplette Vorschau bleibt absichtlich auf noindex.</p></section></section>'''
page('entwuerfe/index.html','Designansichten · Vineria del Este',portal)
(R/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(R/'.nojekyll').touch()
print('Built',len(list(R.rglob('*.html'))),'HTML pages. Original logo:',logo)
